changeSet.sql:
ALTER TABLE "${schema}".survey ADD CONSTRAINT ck_survey_response_review_mode CHECK (response_review_mode IN ('AGGREGATE_ONLY', 'ANONYMOUS_SUBMISSIONS'));
ALTER TABLE "${schema}".survey_question ADD CONSTRAINT ck_survey_question_guidance CHECK (description IS NULL OR char_length(description) <= 2000);
ALTER TABLE "${schema}".survey_question ADD CONSTRAINT ck_survey_question_comment_type CHECK (NOT comment_enabled OR question_type IN ('RATING','SINGLE_CHOICE','MULTIPLE_CHOICE'));
ALTER TABLE "${schema}".survey_answer ADD CONSTRAINT ck_survey_answer_comment_length CHECK (comment IS NULL OR char_length(comment) BETWEEN 1 AND 4000);
CREATE OR REPLACE FUNCTION "${schema}".guard_survey_review_mode() RETURNS trigger LANGUAGE plpgsql AS $body$
BEGIN
 IF OLD.status <> 'DRAFT' AND NEW.response_review_mode IS DISTINCT FROM OLD.response_review_mode THEN
  RAISE EXCEPTION 'Survey response review mode is immutable after publication';
 END IF;
 IF OLD.status = 'CLOSED' AND NEW.status <> 'CLOSED' THEN
  RAISE EXCEPTION 'Closed surveys cannot reopen; create a new survey instead';
 END IF;
 IF OLD.status <> 'DRAFT' AND NEW.status = 'DRAFT' THEN
  RAISE EXCEPTION 'Published surveys cannot return to draft';
 END IF;
 RETURN NEW;
END $body$;
CREATE TRIGGER guard_survey_review_mode BEFORE UPDATE ON "${schema}".survey FOR EACH ROW EXECUTE FUNCTION "${schema}".guard_survey_review_mode();
CREATE INDEX idx_survey_response_review_page ON "${schema}".survey_response (tenant_id, survey_id, id);
